CREATE TABLE payment_outbox (id BIGINT NOT NULL AUTO_INCREMENT,event_id VARCHAR(36) NOT NULL,aggregate_type VARCHAR(50) NOT NULL,aggregate_id VARCHAR(80) NOT NULL,event_type VARCHAR(80) NOT NULL,topic VARCHAR(100) NOT NULL,payload JSON NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'NEW',attempts INT NOT NULL DEFAULT 0,next_attempt_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),published_at TIMESTAMP(6) NULL,PRIMARY KEY(id),CONSTRAINT uk_payment_outbox_event UNIQUE(event_id),KEY ix_outbox_dispatch(status,next_attempt_at));
CREATE TABLE kafka_consumed_event (id BIGINT NOT NULL AUTO_INCREMENT,consumer_group VARCHAR(100) NOT NULL,event_id VARCHAR(36) NOT NULL,topic VARCHAR(100) NOT NULL,processed_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_kafka_consumer_event UNIQUE(consumer_group,event_id));
